// The reply of the local model is checked before it reaches the caller.
// Why: Ollama answers with HTTP 200 even when the requested model is not
// loaded or the context overflows - the body then contains an error message
// or an empty string. Without this check the webhook returns an empty answer
// and the calling application displays it as a valid result.
const raw = $input.first().json || {};
const request = $('Receive the request').first().json.body || {};

// Depending on the endpoint Ollama returns /api/chat (message.content) or /api/generate (response).
const text = String(raw.message?.content ?? raw.response ?? '').trim();
const errorText = String(raw.error || '').trim();

const input = String(request.question || '');
const usable = errorText === '' && text.length >= 2;

return [{
  json: {
    answer: text,
    usable,
    model: raw.model || 'unknown',
    input_chars: input.length,
    answer_chars: text.length,
    // Ollama reports the duration in nanoseconds - milliseconds are enough for the log.
    duration_ms: raw.total_duration ? Math.round(raw.total_duration / 1e6) : null,
    answer_tokens: raw.eval_count ?? null,
    timestamp: new Date().toISOString(),
    processing: 'local',
    failure_reason: usable
      ? ''
      : (errorText || 'The local model returned an empty answer - the model is probably not loaded or the context is too long.'),
  },
}];
